  ["path", {"d":"m4 4 16 16"}],
  ["path", {"d":"M14.24 18.25a10.19 10.19 0 0 1-11.47-5.61 1.5 1.5 0 0 1 0-1.28 10.19 10.19 0 0 1 1.7-2.54"}],
