const EyeOffIcon: Icon = /* @__PURE__ */ createIcon("eye-off", iconNode)

function ReasoningText({ text }: { text: string }) {
  const blocks = text.split(/\n{2,}/)
  return (
    <>
      {blocks.map((block, i) => {
        const heading = HEADING.exec(block)
        return heading ? (
          <p key={i} className="text-(color:--chatcn-fg) font-medium">
            {heading[1]}
          </p>
        ) : (
          <p key={i} className="whitespace-pre-wrap">
            {block}
          </p>
        )
      })}
    </>
  )
}

