const ChevronDownIcon: Icon = /* @__PURE__ */ createIcon("chevron-down", iconNode4)

/** Spoken form for live regions: "12 seconds", "2 minutes 4 seconds". */
function speakChatcnDuration(ms: number) {
  const totalS = Math.max(1, Math.round(ms / 1000))
  const m = Math.floor(totalS / 60)
  const s = totalS % 60
  const part = (n: number, unit: string) => `${n} ${unit}${n === 1 ? "" : "s"}`
  if (m === 0) return part(s, "second")
  return s === 0 ? part(m, "minute") : `${part(m, "minute")} ${part(s, "second")}`
}

/* -------------------------------------------------------------------------------------------------
 * Reasoning
 * -----------------------------------------------------------------------------------------------*/

/**
 * Model reasoning behind one quiet line: "Thinking" with a live timer while it streams, then
 * "Thought for 12 s". Collapsed by default and never closed on a timer: if the user opens it while
 * the model thinks, it stays open. The body grows with smooth height so streamed lines ease in.
 */
export function Reasoning({
  text = "",
  state = "done",
  startedAt,
  durationMs,
  summary,
  redacted = false,
  variant = "inline",
  children,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  className,
  ...props
}: ReasoningProps) {
  const streaming = state === "streaming"
  const { ms } = useChatcnElapsed({ running: streaming, startedAt, durationMs })
  const [openState, setOpenState] = React.useState(defaultOpen)
  const open = openProp ?? openState
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  const shownSummary = React.useMemo(() => {
    if (summary !== undefined) return summary
    if (redacted || !streaming) return undefined
    return deriveSummary(text)
  }, [summary, redacted, streaming, text])

  const seconds = ms === undefined ? undefined : formatChatcnDuration(ms, { precise: false })
  const doneLabel =
    ms === undefined
      ? "Thought for a few seconds"
      : `Thought for ${formatChatcnDuration(Math.max(ms, 1000), { precise: false })}`

  const { innerRef, height } = useChatcnAutoHeight({ enabled: streaming && open })
  const scrollRef = useChatcnStickToBottom(text, { enabled: streaming })

  const isCard = variant === "card"
  const isMinimal = variant === "minimal"

  const header = streaming ? (
    <>
      <ShimmerText className={cn("shrink-0 whitespace-nowrap", isMinimal && "font-normal")}>
        Thinking
      </ShimmerText>
      {seconds && ms !== undefined && ms >= 1000 ? (
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
          {seconds}
        </span>
      ) : null}
      {shownSummary && !isMinimal ? (
        <span
          data-slot="reasoning-summary"
          className="text-(color:--chatcn-fg-subtle) min-w-0 truncate font-normal"
        >
          {shownSummary}
        </span>
      ) : null}
    </>
  ) : (
    <>
      <span
        className={cn(
          "shrink-0 tabular-nums",
          isMinimal ? "font-normal" : "font-medium",
          "text-(color:--chatcn-fg-muted) group-hover/reasoning-trigger:text-(color:--chatcn-fg) transition-colors duration-150",
        )}
      >
        {doneLabel}
      </span>
      {redacted ? (
        <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-w-0 items-center gap-1 [&_svg]:size-3.5">
          <EyeOffIcon aria-hidden="true" className="shrink-0" />
          <span className="truncate">Hidden by the provider</span>
        </span>
      ) : null}
    </>
  )

  const body = redacted ? (
    <p className="text-pretty">
      Reasoning hidden by the provider. It stays encrypted and goes back to the model with the next
      turn, so the answer still builds on it.
    </p>
  ) : (
    (children ??
    (text ? (
      <ReasoningText text={text} />
    ) : (
      <p className="text-(color:--chatcn-fg-subtle)">Starting to think…</p>
    )))
  )

  return (
    <Collapsible.Root
      open={open}
      onOpenChange={setOpen}
      render={<div />}
      data-slot="reasoning"
      data-reasoning-state={streaming ? "streaming" : "done"}
      data-variant={variant}
      className={cn(
        "group/reasoning text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0",
        isCard && "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden",
        className,
      )}
      {...props}
    >
      <Collapsible.Trigger
        className={cn(
          "group/reasoning-trigger flex min-w-0 items-center text-start outline-none select-none",
          "ease-(--chatcn-ease-standard) transition-colors duration-150",
          "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
          isCard && "hover:bg-(color:--chatcn-alpha-100) h-10 w-full gap-2.5 px-3.5",
          variant === "inline" &&
            "rounded-(--chatcn-radius-md) hover:bg-(color:--chatcn-fill-hover) h-8 w-full gap-2.5 px-2",
          isMinimal &&
            "rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg) inline-flex h-7 max-w-full gap-1.5 focus-visible:outline-offset-2",
        )}
      >
        {isMinimal ? null : (
          <span
            aria-hidden="true"
            className={cn(
              "grid size-4 shrink-0 place-items-center [&_svg]:size-4",
              streaming ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-subtle)",
            )}
          >
            <ReasoningIcon />
          </span>
        )}
        <span className="flex min-w-0 flex-1 items-baseline gap-2">{header}</span>
        {isMinimal ? (
          <ChevronRightIcon
            aria-hidden="true"
            className={cn(
              "ease-(--chatcn-ease-out) size-3.5 shrink-0 transition-[rotate] duration-200 rtl:-scale-x-100",
              "group-data-[open]/reasoning:rotate-90 motion-reduce:transition-none",
            )}
          />
        ) : (
          <ChevronDownIcon
            aria-hidden="true"
            className={cn(
              "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) size-4 shrink-0 transition-[rotate] duration-200",
              "group-data-[open]/reasoning:rotate-180 motion-reduce:transition-none",
            )}
          />
        )}
      </Collapsible.Trigger>

      <Collapsible.Panel
        className={cn(
          "h-(--collapsible-panel-height) overflow-hidden",
          "ease-(--chatcn-ease-out) transition-[height,opacity] duration-200 motion-reduce:transition-none",
          "data-[ending-style]:h-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
          "data-[starting-style]:h-0 data-[starting-style]:opacity-0",
        )}
      >
        {/* Smooth height while streaming: the outer box eases to the measured inner height. */}
        <div
          style={{ height }}
          className="ease-(--chatcn-ease-out) overflow-hidden transition-[height] duration-200 motion-reduce:transition-none"
        >
          <div ref={innerRef}>
            <div
              ref={scrollRef}
              data-slot="reasoning-content"
              className={cn(
                "text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) chatcn-scroll flex max-h-72 flex-col gap-2 overflow-y-auto text-pretty",
                isCard && "px-3.5 pt-0.5 pb-3.5",
                variant === "inline" &&
                  "border-(color:--chatcn-border) ms-[15.5px] mt-1 mb-2 border-s ps-[17.5px]",
                isMinimal && "border-(color:--chatcn-border) mt-1 mb-2 border-s ps-3",
              )}
            >
              {body}
            </div>
          </div>
        </div>
      </Collapsible.Panel>

      {/* Announce once, when thinking ends. Never every second. */}
      <span aria-live="polite" className="sr-only">
        {!streaming && ms !== undefined ? `Thought for ${speakChatcnDuration(ms)}` : ""}
      </span>
    </Collapsible.Root>
  )
}

export default Reasoning

